#!/usr/bin/env python3
import collections,json,statistics,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];sys.path.insert(0,str(ROOT/'scripts'))
import evaluate_agents as ev
spec=json.loads((HERE/'audited-benchmark.json').read_text());cases={c['id']:c for c in spec['cases']};primary=json.loads((HERE/'audited-results.json').read_text());content=json.loads((HERE/'content-sensitivity-results.json').read_text());original=json.loads((HERE/'results.json').read_text());runs=primary['runs'];modes=spec['modes'];labels={'single-agent':'Single agent','multi-agent':'Worker + reviewer','comitia':'Comitia worker + reviewer'}
lines=['# Comitia evaluation — September 11, 2026','','Executed against latest remote `main`, commit `570583b0d6cd2ce8ba8e05f1cce6d61b710db611`, in an isolated checkout. **90 real-model trials: six categories × five repetitions × three modes**, using pinned `claude-haiku-4-5-20251001` via Claude Code 2.1.263. Bundled synthetic fixture results are excluded.','','## Aggregate results','','“Checks” measures fixed requirement compliance, including JSON response format. “Content” is a post-hoc sensitivity analysis that extracts JSON from surrounding prose before applying the same checks. Both correct an overly literal match on equivalent architecture entity names and exclude the ambiguous handoff-field check uniformly. Scheduling retains its six other checks. Original as-run scores and every correction remain available.','','| Mode | Checks | Content checks | Full passes | Completed | Captured model cost* | Cost coverage | Input / output tokens* | Mean trial time |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
lines[3:3]=['', f'**Finding:** Comitia scored {100*primary["summary"]["modes"]["comitia"]["quality_mean"]:.1f}% and ordinary worker/reviewer scored {100*primary["summary"]["modes"]["multi-agent"]["quality_mean"]:.1f}% on audited checks. Their mean difference was {100*(primary["summary"]["modes"]["comitia"]["quality_mean"]-primary["summary"]["modes"]["multi-agent"]["quality_mean"]):+.1f} percentage points. Read these alongside the content sensitivity analysis: response formatting and timeouts materially affect the comparison.', '']
for mode in modes:
 s=primary['summary']['modes'][mode];c=content['summary']['modes'][mode];rr=[r for r in runs if r['mode']==mode];captured=sum(ev.cost_of(r,spec) for r in rr)
 lines.append(f'| {labels[mode]} | {100*s["quality_mean"]:.1f}% | {100*c["quality_mean"]:.1f}% | {s["passing_runs"]}/{s["runs"]} | {s["completed_runs"]}/{s["runs"]} | ${captured:.4f} | {100*s["cost_coverage"]:.1f}% | {s["input_tokens"]:,} / {s["output_tokens"]:,} | {s["mean_wall_seconds"]:.1f}s |')
lines+=['','*Captured costs/tokens include returned worker and reviewer usage, including reported thinking and auxiliary usage. Timed-out calls may have unreported usage; these totals are lower bounds where coverage is incomplete. Captured cost includes returned usage from incomplete trials and can exceed the standard harness completed-cost subtotal. Dollar amounts are standard [Anthropic list-price equivalents](https://platform.claude.com/docs/en/about-claude/pricing), not subscription invoices. Local compute cost is excluded equally. The harness suppresses cost efficiency when any trial has incomplete cost capture.','','## Per-category results','','Each cell is **requirement-check score / content-check score**, averaged over five trials. All categories have equal weight.','','| Task category | Single agent | Worker + reviewer | Comitia |','|---|---:|---:|---:|']
for case in spec['cases']:
 cells=[]
 for mode in modes:
  pr=[r for r in runs if r['mode']==mode and r['case_id']==case['id']];cr=[r for r in content['runs'] if r['mode']==mode and r['case_id']==case['id']]
  cells.append(f'{100*statistics.mean(ev.quality_of(r,case)[0] for r in pr):.1f}% / {100*statistics.mean(ev.quality_of(r,case)[0] for r in cr):.1f}%')
 lines.append('| '+case['category']+' — `'+case['id']+'` | '+' | '.join(cells)+' |')
lines+=['','## Detailed per-task measurements','','Cost is all captured usage, including partial usage from incomplete trials, not a completed-only mean.','','| Case | Mode | Passes / completed / trials | Captured USD | Mean seconds | Input / output tokens |','|---|---|---:|---:|---:|---:|']
for case in spec['cases']:
 for mode in modes:
  rr=[r for r in runs if r['mode']==mode and r['case_id']==case['id']]
  lines.append(f'| {case["id"]} | {labels[mode]} | {sum(ev.quality_of(r,case)[1] for r in rr)} / {sum(r["status"]=="completed" for r in rr)} / {len(rr)} | ${sum(ev.cost_of(r,spec) for r in rr):.6f} | {statistics.mean(r["wall_seconds"] for r in rr):.2f} | {sum(c["input_tokens"] for r in rr for c in r["model_calls"]):,} / {sum(c["output_tokens"] for r in rr for c in r["model_calls"]):,} |')
lines+=['','## Paired differences and coordination overhead','','Bootstrap intervals describe this small fixed task set; they do not establish general performance across repositories or models. The CLI does not expose a sampling seed.']
lines+=['']
for mode,c in primary['summary']['comparisons_to_single_agent'].items():
 lines.append(f'- {labels[mode]} vs single: {100*c["quality_delta_mean"]:+.1f} percentage points in requirement checks; bootstrap 95% interval [{100*c["quality_delta_mean_95ci"][0]:+.1f}, {100*c["quality_delta_mean_95ci"][1]:+.1f}]. Wins: {c["quality_wins"]}/{c["paired_runs"]}; ties: {c["quality_ties"]}. Paired cost difference: '+('unavailable because of incomplete usage.' if c['cost_delta_mean_usd'] is None else f'${c["cost_delta_mean_usd"]:+.6f}.'))
for mode,c in content['summary']['comparisons_to_single_agent'].items():
 lines.append(f'- Post-hoc content sensitivity, {labels[mode]} vs single: {100*c["quality_delta_mean"]:+.1f} points; 95% interval [{100*c["quality_delta_mean_95ci"][0]:+.1f}, {100*c["quality_delta_mean_95ci"][1]:+.1f}]. This retains zero scores for timeouts.')
lookup={(r['case_id'],r['replicate'],r['mode']):r for r in runs};qd=[];cd=[];wd=[]
for cid,case in cases.items():
 for rep in range(spec['repetitions']):
  a=lookup[cid,rep,'multi-agent'];b=lookup[cid,rep,'comitia'];qd.append(ev.quality_of(b,case)[0]-ev.quality_of(a,case)[0]);wd.append(b['wall_seconds']-a['wall_seconds'])
  if a['cost_complete'] and b['cost_complete']:cd.append(ev.cost_of(b,spec)-ev.cost_of(a,spec))
ci=ev._bootstrap_ci(qd,5000,spec['seed']+501);cr=[r for r in runs if r['mode']=='comitia'];ops=sum(r['metadata']['comitia_operations'] for r in cr);wall=statistics.mean(r['metadata']['comitia_wall_seconds'] for r in cr)
lines += [f'- Comitia vs the same worker/reviewer workflow without Comitia: {100*statistics.mean(qd):+.1f} points, 95% interval [{100*ci[0]:+.1f}, {100*ci[1]:+.1f}]; paired wall-time difference {statistics.mean(wd):+.2f}s. '+('Paired cost difference suppressed because of incomplete usage.' if len(cd)!=len(qd) else f'Paired cost difference ${statistics.mean(cd):+.6f}.'),f'- Actual Comitia operations: {ops}, with {wall:.3f}s mean coordination-command time per Comitia trial (including setup-only failed trials). The adapter hands the reviewer the exact message body in both modes, so Comitia adds no model-facing text in this experiment. Quality/latency variation between these modes is not evidence that the transport changed reasoning.']
client=json.loads((HERE/'client-metrics.json').read_text());timeouts=json.loads((HERE/'timeout-audit.json').read_text());elapsed=sum(r['wall_seconds'] for r in runs);returned=sum(x['returned_client_sessions'] for x in client.values());invocations=sum(len(list(Path(r['metadata']['artifact']).glob('*-prompt.txt'))) for r in runs)
lines+=['', f"The matrix recorded {elapsed:,.2f} seconds of trial wall time ({elapsed/60:.2f} minutes), with {invocations} model-client invocations: {returned} returned responses and {len(timeouts)} timed out. Returned output thinking-token percentages were "+', '.join(f"{labels[m]} {100*client[m]['thinking_fraction_of_output']:.1f}%" for m in modes)+f". These exclude unavailable timeout usage. {sum(r['stage']=='worker' for r in timeouts)} timeouts occurred in worker calls and {sum(r['stage']=='reviewer' for r in timeouts)} in reviewer calls. {sum(r.get('returned_worker_content_score')==1 for r in timeouts)} reviewer timeouts followed an already-correct worker draft. See [timeout inspection]("+str(HERE/'timeout-audit.json')+") and [client usage detail]("+str(HERE/'client-metrics.json')+")."]
reviews=json.loads((HERE/'audited-review-deltas.json').read_text());lines+=['','## What reviewers changed','']
for label in ('audited','content-sensitivity'):
 for mode in ['multi-agent','comitia']:
  rr=[x for x in reviews if x['mode']==mode and x['label']==label];lines.append(f'- {labels[mode]}, {label}: {sum(x["final_quality"]>x["worker_quality"] for x in rr)} improved, {sum(x["final_quality"]<x["worker_quality"] for x in rr)} worsened, {sum(x["final_quality"]==x["worker_quality"] for x in rr)} tied among {len(rr)} returned final answers.')
lines+=['','## Failures inspected','']
for r in runs:
 case=cases[r['case_id']]
 if ev.quality_of(r,case)[1]:continue
 artifact=Path(r['metadata']['artifact']);f=[q['name'] for q in r['quality'] if not q['earned']]
 if r['status']=='timeout':reason='Model client exceeded its 100-second call limit; usage incomplete. This is not a demonstrated Comitia storage failure.'
 elif r.get('error'):reason='Response format/parser failure: '+r['error']
 else:reason='Failed checks: '+', '.join(f)
 lines.append(f'- `{r["case_id"]}`, {r["mode"]}, repetition {r["replicate"]}: {reason} [Artifact]({artifact}/answer.txt).' if (artifact/'answer.txt').exists() else f'- `{r["case_id"]}`, {r["mode"]}, repetition {r["replicate"]}: {reason} [Trace]({artifact}/events.json).')
lines+=['','Additional manual observations are in [failure inspection notes]('+str(ROOT/'results/manual-audit-notes.md')+'). Those notes distinguish correct code in a malformed response, the grader capitalization defect, genuinely overlapping file schedules, ambiguous handoffs excluded from audited numeric comparisons, and overpromising language missed by automatic communication checks.','','## Existing harness and reliability checks','','- All 79 Go tests passed.','- All 12 evaluator tests passed after fixing the fixture runner executable bit; before the fix, the documented fixture invocation produced 12 permission-denied harness errors.','- All 17 independent grader/audit reference and negative-control tests passed.','- Existing process stress harness passed with 12 workers, 1,200 writes, 120 deduplicated retries, 1,200 replayed messages, exactly one winner among 12 competing claims, one expired-lease recovery and rejection of a stale completion. Runtime: 4.920 seconds. These are subprocess clients, not LLM agents.','','## Interpretation and limits','','The extra reviewer can repair response formatting and some scheduling mistakes. That benefit is shared by the ordinary worker/reviewer baseline. A fixed durable transport does not itself make the same model prompts reason better. Comitia’s reliability tests demonstrate durable replay, exclusivity and stale-lease handling; this experiment does not estimate their economic benefit under production crashes or competing autonomous agents.','','For small factual and already-correct answers, the extra review workflow consumes more model calls. Comitia adds a small local command overhead on top. For coordination-sensitive work, Comitia provides verified durable mechanisms, but choosing when and how to use them needs a separate dynamic-agent or fault-injection comparison. All tasks here are bounded, tools are disabled for models, and the adapter performs coordination. Architecture and communication scores are structured checks, not holistic expert judgments. There is no equal-token-budget or single-agent self-review control; benefits of an extra call cannot establish that separate agent identities are necessary. Some check failures arise from strict formatting. The ambiguous schema/value handoff example remains in original scores but is excluded from audited scores for every mode.','','One client capability probe and one Comitia integration pilot were excluded from the 90 trials; their returned list-price equivalents were $0.002358 and $0.003686 respectively. No real matrix trial was discarded or silently retried.','','## Reproducibility and changes','','- [Method, prompts, pricing and execution contract]('+str(HERE/'README.md')+').','- [Audited results JSON]('+str(HERE/'audited-results.json')+'); [original as-run JSON]('+str(HERE/'results.json')+'); [content sensitivity JSON]('+str(HERE/'content-sensitivity-results.json')+').','- [Score corrections]('+str(HERE/'score-corrections.json')+'); [environment and hashes]('+str(ROOT/'results/provenance.json')+').','- Only the supplied fixture runner executable bit changed. New adapter, cases, graders and reports are isolated in this checkout. Nothing was committed or pushed, and the old local checkout and synced sources were untouched.','']
(ROOT.parent/'comitia-evaluation-report.md').write_text('\n'.join(lines));print(ROOT.parent/'comitia-evaluation-report.md')
